BEGIN;CREATE OR REPLACE FUNCTION office_private.inst_require(w uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.office_memberships m JOIN public.office_industry_spaces s ON s.workspace_id=m.workspace_id AND s.industry_id='church' WHERE m.workspace_id=w AND m.user_id=auth.uid() AND m.status='active') THEN RAISE EXCEPTION 'Institutions membership required' USING ERRCODE='42501';END IF;IF office_private.inst_role(w) IS NULL AND EXISTS(SELECT 1 FROM public.office_memberships m WHERE m.workspace_id=w AND m.user_id=auth.uid() AND m.role='owner' AND m.status='active') AND NOT EXISTS(SELECT 1 FROM public.office_institutions_settings z WHERE z.workspace_id=w AND z.initialized) THEN RETURN;END IF;IF office_private.inst_role(w) IS NULL THEN RAISE EXCEPTION 'Institutions module role required' USING ERRCODE='42501';END IF;END $$;ALTER TABLE public.office_institutions_reports ADD COLUMN IF NOT EXISTS branch_id uuid;CREATE INDEX IF NOT EXISTS office_inst_reports_page ON public.office_institutions_reports(workspace_id,report_type,period_end DESC,id);ALTER TABLE public.office_institutions_reports ENABLE ROW LEVEL SECURITY;DROP POLICY IF EXISTS deny_direct_office_institutions_reports ON public.office_institutions_reports;CREATE POLICY deny_direct_office_institutions_reports ON public.office_institutions_reports FOR ALL USING(false) WITH CHECK(false);CREATE OR REPLACE FUNCTION office_private.inst_actor_branch(w uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT r.branch_id FROM public.office_institutions_roles r WHERE r.workspace_id=w AND r.user_id=auth.uid() AND r.active AND r.role<>'institution_admin' ORDER BY r.updated_at DESC LIMIT 1 $$;CREATE OR REPLACE FUNCTION office_private.inst_cap(w uuid,c text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE r text;owner_ok boolean;BEGIN SELECT office_private.inst_role(w) INTO r;SELECT EXISTS(SELECT 1 FROM public.office_memberships m JOIN public.office_industry_spaces s ON s.workspace_id=m.workspace_id AND s.industry_id='church' WHERE m.workspace_id=w AND m.user_id=auth.uid() AND m.role='owner' AND m.status='active') INTO owner_ok;IF c='manage' AND r IS NULL AND owner_ok AND NOT EXISTS(SELECT 1 FROM public.office_institutions_settings WHERE workspace_id=w AND initialized) THEN RETURN true;END IF;IF r IS NULL THEN RETURN false;END IF;RETURN CASE c WHEN 'manage' THEN r='institution_admin' WHEN 'people' THEN r IN('institution_admin','registrar','hr_officer','privacy_officer') WHEN 'governance' THEN r IN('institution_admin','governance_secretary','approver') WHEN 'finance' THEN r IN('institution_admin','treasurer','approver') WHEN 'approve' THEN r='approver' WHEN 'facilities' THEN r IN('institution_admin','facility_manager') WHEN 'programmes' THEN r IN('institution_admin','programme_coordinator') WHEN 'staff' THEN r IN('institution_admin','hr_officer') WHEN 'safeguarding' THEN r IN('safeguarding_officer','privacy_officer') WHEN 'privacy' THEN r IN('institution_admin','privacy_officer') WHEN 'reports' THEN r IS NOT NULL WHEN 'audit' THEN r='institution_admin' ELSE false END;END $$;CREATE OR REPLACE FUNCTION office_private.inst_safe_row(r record) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE d jsonb:=jsonb_build_object('id',r.id,'workspace_id',r.workspace_id,'status',r.status,'version',r.version,'created_by',r.created_by,'created_at',r.created_at,'updated_at',r.updated_at);k text;a text[];BEGIN a:=CASE r.resource WHEN 'organizations' THEN ARRAY['code','name','jurisdiction','legal_form','registration_authority','registration_reference','constitution_reference','address_public','tin_reference'] WHEN 'branches' THEN ARRAY['organization_id','code','name','location_public'] WHEN 'people' THEN ARRAY['code','branch_id','status_public'] WHEN 'attendance' THEN ARRAY['event_id','branch_id','attendance_date','present_count','absent_count'] WHEN 'safeguarding' THEN ARRAY['code','branch_id','reported_on','category_public'] ELSE ARRAY['code','name','title_public','purpose_public','reference','branch_id','fund_id','event_id','status','currency','amount','cost','capacity','facility_id','programme_id','organization_id','budget_id','method','direction','period_start','period_end','source_url','due_on','requested_on','received_on'] END;FOREACH k IN ARRAY a LOOP IF r.data ? k THEN d:=d||jsonb_build_object(k,r.data->k);END IF;END LOOP;RETURN d;END $$;CREATE OR REPLACE FUNCTION office_private.inst_resource_cap(r text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN r IN('organizations','branches','bodies','appointments','meetings','resolutions') THEN 'governance' WHEN r IN('funds','budgets','contributions','payment_requests','bank_lines','reconciliations','ledger') THEN 'finance' WHEN r IN('facilities','assets','asset_moves') THEN 'facilities' WHEN r IN('programmes','events','attendance') THEN 'programmes' WHEN r IN('staff_assignments','credentials','team_members') THEN 'staff' WHEN r='safeguarding' THEN 'safeguarding' WHEN r IN('filings','evidence','privacy_requests') THEN 'privacy' ELSE NULL END $$;CREATE OR REPLACE FUNCTION office_private.inst_report_cap(rt text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT CASE rt WHEN 'finance' THEN 'finance' WHEN 'governance' THEN 'governance' WHEN 'compliance' THEN 'privacy' WHEN 'assets' THEN 'facilities' WHEN 'programmes' THEN 'programmes' ELSE NULL END $$;REVOKE ALL ON FUNCTION office_private.inst_actor_branch(uuid),office_private.inst_resource_cap(text),office_private.inst_report_cap(text) FROM PUBLIC,anon,authenticated;COMMIT;
